                     const uint8_t owner_key[32]);
int bkpc_grants_set(struct bkpc_grants_s *, uint64_t expected,
                    const uint8_t transaction[16], const uint8_t client_id[16],
                    const uint8_t pc_key[32], uint32_t capabilities);
