#define BKCONTROL_REQUEST_MAX (16u + BKCONTROL_CONFIG_APPEND_MAX)
#define BKCONTROL_RESPONSE_SIZE 40u
#define BKCONTROL_CAMERA_BLOCK_SIZE 512u
