/* NCA1: read-only16-byte scene capability/current-admission snapshot. */
#define BKCONTROL_CONFIG_NFC_SCENE 13u
#define BKCONTROL_CONFIG_PC_AUTHORIZATION 14u
/* PTE1/PTS1 volatile task events; see bk7258_pc_tasks.h. */
